create role anon;
create role authenticated;
create role service_role;
create schema auth;
create function auth.uid() returns uuid language sql stable as $$
  select '00000000-0000-0000-0000-000000000001'::uuid
$$;

create table public.users (user_id bigint primary key, first_name text, last_name text);
create table public.buyers (buyer_user_id bigint primary key, user_id bigint);
create table public.carts (cart_id bigint primary key, buyer_user_id bigint);
create table public.cart_items (cart_item_id bigint primary key, cart_id bigint, commodity_id bigint);
create table public.orders (order_id bigint primary key, cart_item_id bigint, order_status text);
create table public.reviews (
  review_id bigint primary key,
  order_id bigint,
  rating numeric,
  comment text,
  created_at timestamptz default now()
);

create table public.rider_ratings (
  rating_id bigint primary key
);

insert into public.reviews(review_id) values (1);
insert into public.rider_ratings(rating_id) values (2);

create table public.admin_review_responses (
  response_id bigint generated by default as identity primary key,
  review_type text,
  review_id text,
  response_mode text,
  message text,
  created_at timestamptz default now()
);

